/// Wonky Drive's localizations (suite 11 §4): ARB files in this folder,
/// generated by `flutter gen-l10n` (`l10n.yaml`) into `gen/`.
///
/// Widgets use [driveL10n]; code without a `BuildContext` (controllers,
/// commands, toasts) uses [driveL10nOf] with the shell services.
library;

import 'package:flutter/widgets.dart';
import 'package:wonky_app/wonky_app.dart';

import 'gen/drive_localizations.dart';

export 'gen/drive_localizations.dart';

/// The Drive strings for [context] (English when the delegate is missing).
DriveLocalizations driveL10n(BuildContext context) =>
    Localizations.of<DriveLocalizations>(context, DriveLocalizations) ??
    driveL10nEnglish;

/// The Drive strings in the shell's current locale (no `BuildContext`).
DriveLocalizations driveL10nOf(ShellServices services) {
  final c = services.navigatorContext;
  return c == null ? driveL10nEnglish : driveL10n(c);
}

/// English strings (the template locale).
final DriveLocalizations driveL10nEnglish = lookupDriveLocalizations(
  const Locale('en'),
);
